"""Zoo 1.123.0: a fixtures build can leave a kind out -- for one sign a building, the walker walking cold run 9386:
"in real life this would be 1 sign" (the factory's `docs/findings/walk_2026-10-23_9386/`, finding 1).

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * zoo_keeper/core/fixtures.py -- `plan(..., skip=)`.
  * zoo_keeper/bpylayer/build.py -- `build_fixtures` passes `skip`.
  * tools/zoo_cli.py -- `--skip-fixture-types`.
  * tests/test_fixture_skip.py -- new.
  * VERSION 1.122.0 -> 1.123.0, CHANGELOG.

Generated by `patches/one_sign/gen_zoo_skip_types.py` from a proven clone.

    python patches/patch_zoo_skip_types.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "zoo"
PINS = {'zoo_keeper/core/fixtures.py': 'b097ca4c9efdc196', 'zoo_keeper/bpylayer/build.py': 'e107f891f31cfd46', 'tools/zoo_cli.py': 'fbf151f8dea8cfd6'}
EDITS = {'zoo_keeper/core/fixtures.py': [('lines 237-237', 'def plan(manifest: dict, types=None) -> dict:\n', 'def plan(manifest: dict, types=None, skip=None) -> dict:\n'), ('lines 241-241', '    type in FIXTURES). Returns::\n', "    type in FIXTURES). ``skip``: optional iterable of anchor types to leave\n    out, whatever ``types`` says (1.123.0) -- a caller that wants everything\n    but one kind names that kind, not every other: Level Factory leaves out a\n    shell's ``sign`` when its street band names the business, one sign a\n    building (the walker, cold run 9386). Returns::\n"), ('lines 248-249', '    wanted = set(types) if types else set(FIXTURES)\n    placements, skipped, counts = [], [], {}\n', '    wanted = set(types) if types else set(FIXTURES)\n    left_out = set(skip or ())\n    placements, skipped, counts = [], [], {}\n'), ('lines 278-279', '                            "reason": "no fixture species for this type"})\n            continue\n', '                            "reason": "no fixture species for this type"})\n            continue\n        if t in left_out:\n            skipped.append({"id": aid, "type": t,\n                            "reason": "left out by --skip-fixture-types"})\n            continue\n')], 'zoo_keeper/bpylayer/build.py': [('lines 751-751', '    plan = fixtures_mod.plan(lights_manifest, types=opts.get("types"))\n', '    plan = fixtures_mod.plan(lights_manifest, types=opts.get("types"), skip=opts.get("skip"))\n')], 'tools/zoo_cli.py': [('lines 139-140', '                         "per-building.")\n    ap.add_argument("--sign-pack", dest="sign_pack",\n', '                         "per-building.")\n    ap.add_argument("--skip-fixture-types", dest="skip_fixture_types",\n                    help="with --fixtures: comma list of anchor types to leave "\n                         "out whatever --fixture-types says (1.123.0), e.g. "\n                         "\'sign\' for a shell whose street band already names "\n                         "the business -- one sign a building")\n    ap.add_argument("--sign-pack", dest="sign_pack",\n'), ('lines 581-582', '        types = [t.strip() for t in args.fixture_types.split(",") if t.strip()]\n\n', '        types = [t.strip() for t in args.fixture_types.split(",") if t.strip()]\n    skip = None\n    if getattr(args, "skip_fixture_types", None):\n        skip = [t.strip() for t in args.skip_fixture_types.split(",") if t.strip()]\n\n'), ('lines 585-585', '        print(json.dumps(fixtures_mod.plan(manifest, types=types),\n', '        print(json.dumps(fixtures_mod.plan(manifest, types=types, skip=skip),\n'), ('lines 595-595', '                 "seed": args.seed, "types": types,\n', '                 "seed": args.seed, "types": types, "skip": skip,\n')]}
NEW_FILES = {'tests/test_fixture_skip.py': '"""A fixtures build leaves out named anchor types (1.123.0): one sign a building, the walker walking cold run 9386 --\n"in real life this would be 1 sign". FAILS ON 1.122.0, whose `plan` takes no `skip`."""\nfrom zoo_keeper.core import fixtures\n\n\ndef _manifest():\n    return {"light_manifest_version": "1.1.0", "building_id": "shop", "anchors": [\n        {"id": "ext_0_S_sign", "type": "sign", "pos": [-3.5, -9.35, 2.55], "rot_y": 270.0, "size": [2.4, 0.6]},\n        {"id": "ceiling_0", "type": "fluorescent", "pos": [0.0, 0.0, 3.0]}]}\n\n\ndef test_a_skipped_type_builds_nothing_and_says_why():\n    p = fixtures.plan(_manifest(), skip=["sign"])\n    assert {pl["type"] for pl in p["placements"]} == {"fluorescent"}\n    assert any(s["id"] == "ext_0_S_sign" and "skip-fixture-types" in s["reason"] for s in p["skipped"])\n\n\ndef test_no_skip_builds_the_door_box_as_before():\n    p = fixtures.plan(_manifest())\n    assert {pl["type"] for pl in p["placements"]} == {"fluorescent", "sign"}\n'}
CHANGELOG = '## [1.123.0] - a fixtures build can leave a kind out\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 1), of a\npharmacy with its band along the parapet and a lit box over its door: "in real life this would be 1 sign".\n\n### Added\n- **`fixtures.plan(..., skip=)` and `--skip-fixture-types`**: anchor types left out whatever `--fixture-types` says,\n  each said in the plan\'s `skipped` ("left out by --skip-fixture-types"). A caller that wants everything but one kind\n  names that kind, not every other -- an allow-list of the rest would go stale the day a kind is added. Level Factory\n  0.241.0 leaves out a shell\'s `sign` when its street band names the business.\n\n### Tests\n- `tests/test_fixture_skip.py` (new): a skipped `sign` builds nothing and says why; no skip builds the door box as\n  before. Fails on 1.122.0.\n\n'
OLD_VERSION, NEW_VERSION = '1.122.0', '1.123.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
